import { useState, useTransition, useMemo } from 'react';

// Generate mock data:
const ALL_QUESTS = Array.from({ length: 5000 }, (_, i) => ({
  id: i,
  title: `Quest ${i}: ${['Slay', 'Find', 'Deliver', 'Rescue', 'Explore'][i % 5]} item ${i}`,
}));

export default function QuestSearch() {
  const [query, setQuery] = useState('');
  const [filteredQuests, setFilteredQuests] = useState(ALL_QUESTS);
  const [isPending, startTransition] = useTransition();

  function handleChange(e) {
    const value = e.target.value;
    setQuery(value);
    // TODO: wrap the filter in startTransition
    setFilteredQuests(ALL_QUESTS.filter(q =>
      q.title.toLowerCase().includes(value.toLowerCase())
    ));
  }

  return (
    <div>
      <input
        data-testid="search"
        value={query}
        onChange={handleChange}
        placeholder="Search quests..."
      />
      {/* TODO: show pending indicator */}
      <p>{filteredQuests.length} quests</p>
      <ul>
        {filteredQuests.slice(0, 50).map(q => (
          <li key={q.id}>{q.title}</li>
        ))}
      </ul>
    </div>
  );
}
